cker($cont) {	$cont.prop('readonly', true).datepicker({		closeText: '닫기',		prevText: '',		nextText: '',		currentText: '오늘',		monthNames: ['1월(JAN)','2월(FEB)','3월(MAR)','4월(APR)','5월(MAY)','6월(JUN)','7월(JUL)','8월(AUG)','9월(SEP)','10월(OCT)','11월(NOV)','12월(DEC)'],		monthNamesShort: ['1월','2월','3월','4월','5월','6월','7월','8월','9월','10월','11월','12월'],		dayNames: ['일','월','화','수','목','금','토'],		dayNamesShort: ['일','월','화','수','목','금','토'],		dayNamesMin: ['일','월','화','수','목','금','토'],		weekHeader: 'Wk',		dateFormat: 'yy-mm-dd',		defaultDate: '+1w',		firstDay: 0,		isRTL: false,		showMonthAfterYear: true,		yearSuffix: '년 ',		changeMonth: true,		changeYear: true,		yearRange: '1921:c+5'	});}function boardDel(val){	if(confirm("삭제 하시겠습니까?")) {		$.post("/module/board/ajax_board_del.php", { evnMode: "delete", g_idx: val, boardid: "<?=$arrBoardInfo["list"][0]["boardid"]?>" },		function(data){			//alert(data);			doLoad();		});	}}function doLoad(){	location.reload();}// SMS sending functionfunction sendSMS(selectedRows) {    var smsTemplateId = $('select[name=sms_options]').val();    if (!smsTemplateId) {        alert('문자발송 리스트에서 발송할 내용을 선택해주세요.');        return;    }    var phones = [];    var message = smsTemplateId;    // Collect phone numbers from selected rows    $(selectedRows).each(function() {        var row = $(this).closest('tr');        var phone = row.find('td:eq(5)').text().trim(); // Get phone number from the 6th column        if (phone) {            phones.push(phone);        }    });    if (confirm(phones.length + '개의 번호로 문자를 발송하시겠습니까?')) {        $.ajax({            url: '/module/board/ajax_board_send_sms.php',            type: 'POST',            data: {                phones: phones.join(','),                messages: message, // Send the same message to all phone numbers                template_id: smsTemplateId            },            success: function(response) {                if (response === "true") {                    alert('문자가 발송되었습니다.');                } else {                    alert('문자 발송 중 오류가 발생했습니다: ' + response.message);                }            },            error: function() {                alert('문자 발송 요청 중 오류가 발생했습니다.');            }        });    }}// Email sending functionfunction sendEmail(selectedRows) {    var emailTemplateId = $('select[name=email_options]').val();    if (!emailTemplateId) {        alert('이메일발송 리스트에서 발송할 내용을 선택해주세요.');        return;    }    var emails = [];    var idx = emailTemplateId;    // Collect email addresses from selected rows    $(selectedRows).each(function() {        var row = $(this).closest('tr');        var email = row.data('email'); // Get email address from data attribute        if (email) {            emails.push(email);        }    });    if (confirm(emails.length + '개의 이메일로 발송하시겠습니까?')) {        $.ajax({            url: '/module/board/ajax_board_send_mail.php',            type: 'POST',            data: {                emails: emails.join(','),                idx: idx,                etc_3 : '<?=$smsMailId?>'            },            success: function(response) {                if (response === "true") {                    alert('이메일이 발송되었습니다.');                } else {                    //alert(response);                    alert('이메일 발송 중 오류가 발생했습니다: ' + response.message);                }            },            error: function() {                alert('이메일 발송 요청 중 오류가 발생했습니다.');            }        });    }}$(function(){    $(".check_all").click(function(){        var chk = $(this).is(":checked");//.attr('checked');        if(chk) $(".chk_list").prop('checked', true);        else  $(".chk_list").prop('checked', false);    });});// 순서 변경$(function() {	/*	$("#sortWrap").sortable({		axis: "y",		containment: "parent",		update: function (event, ui) {			var order = $(this).sortable('toArray', {				attribute: 'data-order'			});			console.log(order);			fnOrderSave(order);		}	});	*/});var arrIdx=[];function fnOrderSave(order){	arrIdx = order;	fnGoodOrderby();}function fnGoodOrderby(){	var idxs = "";	var comma = "";	for(var i=0;i<arrIdx.length;i++){		idxs += comma+arrIdx[i];		comma = "|";	}	//alert(idxs)	if(idxs){		$.post("/module/board/ajax_orderby_board.php", { "gidx": idxs, "tn":"tbl_board_<?=$arrBoardInfo["list"][0]["boardid"]?>" },			function(data){				if(data){				//	alert(data);					location.reload();				}			}		);	}else{		alert('변경된 순서가 없습니다.');	}}// 메인노출function fnAjaxYN(objt, sf){	var apiUrl = "/module/shop/ajax_edit_def_yn.php";	var gidx = $(objt).val();	var chk = $(objt).is(":checked");//.attr('checked');	var yn = "";	if(chk){		yn = "Y";	}else{		yn = "N";	}	//	alert(yn)	$.post(apiUrl, {		"gidx":gidx,"yn":yn,"sf":sf,"tn":"tbl_board_ourstory"	}, function(data){	//	alert(data);		if(data=="true"){			location.reload();		}else{			alert(data);		}	});}function fnCat1(tval){    $.post("/module/shop/ajax_selectbox_category.php", { snum : '2',cat_no: tval, eventMd : '<?=$_GET['eventMd']?>'},        function(data){            if(data){                $("#cat_02").html(data);            }else{                alert("실패.");            }        }    );    fnCatNo();}function fnCat2(tval){    $.post("/module/shop/ajax_selectbox_category.php", { snum : '3',cat_no: tval },        function(data){            if(data){                $("#cat_03").html(data);            }else{                alert("실패.");            }        }    );    fnCatNo();}function fnCat3(tval){    fnCatNo();}function fnCatNo(){    var cat_no1 = $("#cat1 option:selected").val();    var cat_no2 = $("#cat2 option:selected").val();    var cat_no3 = $("#cat3 option:selected").val();    var cat_no = "";    if(cat_no3 && cat_no2 && cat_no1){        cat_no = cat_no3;    }else if(cat_no2 && cat_no1){        cat_no = cat_no2;    }else{     